mapper.select:
select d.name name, sum(oi.quantity) value from order_item oi inner join dish d on oi.dish_id = d.id inner join stall s on d.stall_id = s.id inner join orders o on oi.order_id = o.id where o.status = 3
and s.merchant_id = #{merchantId}
group by d.id, d.name order by value desc limit 10
